package com.nypunya.assessment.entity;
import javax.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="quiz_attempts",uniqueConstraints=@UniqueConstraint(name="uk_attempt_quiz_student_number",columnNames={"quiz_id","student_id","attempt_number"}),indexes=@Index(name="idx_attempt_student_quiz",columnList="student_id,quiz_id"))
public class QuizAttempt { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="quiz_id",nullable=false) private Long quizId; @Column(name="student_id",nullable=false) private Long studentId; @Column(name="attempt_number",nullable=false) private Integer attemptNumber; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private QuizAttemptStatus status=QuizAttemptStatus.IN_PROGRESS; @Column(name="started_at",nullable=false) private LocalDateTime startedAt; @Column(name="submitted_at") private LocalDateTime submittedAt; @Column(name="score") private Integer score; @PrePersist void prePersist(){if(startedAt==null)startedAt=LocalDateTime.now();} public Long getId(){return id;} public Long getQuizId(){return quizId;} public void setQuizId(Long v){quizId=v;} public Long getStudentId(){return studentId;} public void setStudentId(Long v){studentId=v;} public Integer getAttemptNumber(){return attemptNumber;} public void setAttemptNumber(Integer v){attemptNumber=v;} public QuizAttemptStatus getStatus(){return status;} public void setStatus(QuizAttemptStatus v){status=v;} public LocalDateTime getStartedAt(){return startedAt;} public LocalDateTime getSubmittedAt(){return submittedAt;} public void setSubmittedAt(LocalDateTime v){submittedAt=v;} public Integer getScore(){return score;} public void setScore(Integer v){score=v;} }
